3666: # Health of one ENDPOINT (provider_fingerprint - never the alias) from the ledgers of all
3667: # tasks. Entries recorded before 0.3.0 count as the built-in openai endpoint; entries with
3668: # an unresolved identity (empty fingerprint) are ignored. A failure's class comes from its
3669: # provider_failure, else (older entries) from its bridge_outcome. Newest wins: a later
3670: # successful run clears an earlier auth or quota failure ("later" by completion: finished_at,
3671: # else when + wall_seconds; ties by n). $UtcNow: the consult clock
3672: # (Get-ConsultClock -Peek), so a test can freeze time.
3673: #   Auth         the newest of {success, auth failure} is an auth failure <= 24 h old
3674: #   Quota        the newest of {success, quota failure} is a quota failure that still
3675: #                blocks: its RetryAfter lies in the future, or it has no RetryAfter and is
3676: #                <= 60 min old (a RetryAfter in the past clears it)
3677: #   QuotaKnown   [bool] Quota is set and names its reset time (RetryAfter)
3678: #   LastLimit    the newest quota failure <= 24 h old (informational)
3679: #   LastFailure  the newest failure of any class <= 24 h old (informational)
3680: #   RecentUsable the newest usable reply <= 60 min old (wave 18: an engine's sign-in is then
3681: #                evidenced without a network check - Get-EngineCredential)
3682: # Each record is $null or { Class; Code; Message; When; AgeMinutes (a `when` in the future
3683: # counts as now: 0); RetryAfter (DateTimeOffset or $null: provider_failure.retry_after, else
3684: # Get-RetryAfter -ReferenceOffset on the recorded message with the failure's `when` as
3685: # reference); RetryAfterIso ('' when none); RetryAfterBasis ('ledger' | 'message (reference
3686: # offset)' | ''); Until (RetryAfter, else When + 60 min) }.
3687: function Get-EndpointHealth {
3688:     param([object[]]$Consults, [string]$Fingerprint, [datetime]$UtcNow = [datetime]::UtcNow)
3689:     $h = [pscustomobject]@{ Auth = $null; Quota = $null; QuotaKnown = $false; LastLimit = $null; LastFailure = $null; RecentUsable = $null }
3690:     if (-not $Fingerprint) { return $h }
3691:     $records = New-Object System.Collections.Generic.List[object]
3692:     foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
3693:         $rev = Get-PropertyValue $c 'reviewer' $null
3694:         $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
3695:         if (-not $fp -or $fp -ne $Fingerprint) { continue }
3696:         $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
3697:         if (-not $outcome) { continue }
3698:         $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
3699:         if ($null -eq $at) { continue }
3700:         # A failure stamped in the future (clock skew, a mislabelled zone) counts as now:
3701:         # its age is clamped to 0, it is never skipped (F15-4).
3702:         $age = [Math]::Max(0, ($UtcNow - $at.UtcDateTime).TotalMinutes)
